106	std::string BuildExp(uint64_t val)
107	{
108	    char buff[256];
109	    std::string name = "";
110	    uint64_t offset = ARG_STEP;
111	
112	    for (auto it : GetArgVal()) {
113	        if (offset > val - it.second) {
114	            offset = val - it.second;
115	            name = it.first;
116	        }
117	    }
118	    if (offset != 0) {
119	        int ret = snprintf_s(buff, sizeof(buff), sizeof(buff), "(((uint64_t)%s) + 0x%lx)", name.c_str(), offset);
120	        if (ret <= 0) {
121	            raise(SIGABRT);
122	        }
123	    } else {
124	        int ret = snprintf_s(buff, sizeof(buff), sizeof(buff), "%s", name.c_str());
125	        if (ret <= 0) {
126	            raise(SIGABRT);
127	        }
128	    }
129	    return std::string(buff);
130	}
131	
132	bool FileExists(std::string fileName)
133	{
134	    struct stat buffer;
135	    return stat(fileName.c_str(), &buffer) == 0;
136	}
137	
138	uint64_t GetTime()
139	{
140	    struct timespec ts {};
141	    (void)clock_gettime(CLOCK_MONOTONIC, &ts);
142	    uint64_t milliseconds = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
143	    return milliseconds;
144	}
145	
146	std::string GetFileName()
147	{
148	    std::string fileName = "/tmp/tmpfile_" + std::to_string(GetTime()) + "_" + std::to_string(getpid());
149	    while (FileExists(fileName)) {
150	        fileName = "/tmp/tmpfile_" + std::to_string(GetTime()) + "_" + std::to_string(getpid());
151	    }
152	    return fileName;
153	}
154	
155	void HandleError(bool condition, const std::string& message, int fd)
156	{
157	    if (condition) {
158	        std::cerr << "GmAlloc Error: " << message << std::endl;
159	        close(fd);
160	        raise(SIGABRT);
161	    }
162	}
163	
164	/**
165	 * GM memory structure:
166	 * protect user tail 4k memory
167	 *
168	 * 0                      4K  <8K                          -4K                   END
169	 * +----------------------+----+----------------------------+----------------------+
170	 * |  4K HEADER READ ONLY |////|<------- USER SIZE -------->| 4K TAIL CANNOT ACCESS|
171	 * +----------------------+----+----------------------------+----------------------+
172	 *                             ^                            ^
173	 *       HEADER                USER START                   USER TAIL 4K ALIGN
174	 */
175	
176	void* GmAlloc(size_t size)
177	{
178	    size_t pageSize = getpagesize();
179	    size_t alignedExtraPageSize = pageSize * 2 + pageSize - 1; // 2 pages for header and tail
180	    if (size > (SIZE_MAX - alignedExtraPageSize)) {
181	        std::cerr << "GmAlloc Error: input size overflow detected." << std::endl;
182	        raise(SIGABRT);
183	    }
184	    size_t newSize = (size + alignedExtraPageSize) & (~(pageSize - 1)); // align to multiple page size
185	    std::string fileName = GetFileName();
186	    int fd = open(fileName.c_str(), O_RDWR | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
187	    HandleError(fd == -1, "Failed to open file: " + std::string(strerror(errno)), fd);
188	    int res = ftruncate(fd, newSize);
189	    if (errno == EFBIG) {
190	        HandleError(res != 0, "The /tmp directory does not have enough space.", fd);
191	    }
192	    auto filePtr = mmap(nullptr, newSize, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
193	    HandleError(filePtr == MAP_FAILED, "Error map file to ptr, error code: " + std::string(strerror(errno)), fd);
194	    if (static_cast<int>(reinterpret_cast<intptr_t>(filePtr)) == -1) {
195	        std::cout << "Error map file to ptr, error code: " << errno << std::endl;
196	        raise(SIGABRT);
197	    }
198	    ShmMemT* mem = static_cast<ShmMemT*>(filePtr);
199	    mem->fd = fd;
200	    mem->size = newSize;
201	    mem->magicCode = 0xdeadbeef;
202	    errno_t ret = strcpy_s(mem->fileName, sizeof(mem->fileName), fileName.c_str());
203	    HandleError(ret != EOK, "strcpy_s failed, ret = " + std::to_string(ret), fd);
204	    (void)mprotect(mem, pageSize, PROT_READ);
205	    (void)mprotect(reinterpret_cast<uint8_t*>(mem) + newSize - pageSize, pageSize, PROT_NONE);
206	    void* userStart = reinterpret_cast<uint8_t*>(mem) + newSize - pageSize - size;
207	    void* headerTail = reinterpret_cast<uint8_t*>(mem) + pageSize;
208	    if (userStart != headerTail) {
209	        size_t emptySize = (uint8_t*)userStart - (uint8_t*)headerTail;
210	        if (emptySize > 0) {
211	            memset_s(headerTail, emptySize, 0xff, emptySize);
212	        }
213	    }
214	    return userStart;
215	}
216	
217	void* GmGetHeader(void* ptr)
218	{
219	    int pageSize = getpagesize();
220	    return (void*)(((uint64_t)ptr & (~(pageSize - 1))) - pageSize);
221	}
222	
223	uint64_t GmGetUserSize(uint64_t addr)
224	{
225	    uint64_t pageSize = getpagesize();
226	    if (mprotect(reinterpret_cast<void*>(addr & ~(pageSize - 1)), pageSize, PROT_READ | PROT_WRITE) != 0) {
227	        return 0;
228	    }
229	    ShmMemT* mem = static_cast<AscendC::ShmMemT*>(AscendC::GmGetHeader(reinterpret_cast<void*>(addr)));
230	    size_t size = mem->size;
231	    uint64_t offset = addr - (addr & ~(pageSize - 1));
232	    return size - DOUBLE * pageSize - offset;
233	}
234	
235	void CheckEmptyGmValied(void* ptr)
236	{
237	    int pageSize = getpagesize();
238	    void* headerTail = (void*)((uint64_t)ptr & (~(pageSize - 1)));
239	    if (headerTail != ptr) {
240	        for (uint8_t* tmpPtr = (uint8_t*)headerTail; tmpPtr < (uint8_t*)ptr; tmpPtr++) {
241	            if (*(uint8_t*)tmpPtr != 0xff) {
242	                std::cout << "Empty memory is accessed ! or \
243	                              this memory has been released more than one time."
244	                          << std::endl;
245	                raise(SIGABRT);
246	            }
247	        }
248	    }
249	}
250	
251	void GmFree(void* ptr)
252	{
253	    int pageSize = getpagesize();
254	    CheckEmptyGmValied(ptr);
255	    int fd;
256	    size_t size;
257	    char file[256];
258	    ShmMemT* mem = static_cast<ShmMemT*>(GmGetHeader(ptr));
259	    fd = mem->fd;
260	    size = mem->size;
261	    errno_t ret = strcpy_s(file, sizeof(file), mem->fileName);
262	    if (ret != EOK) {
263	        std::cout << "strcpy_s failed, ret = " << ret << std::endl;
264	        raise(SIGABRT);
265	    }
266	    munmap(mem, size);
267	    close(fd);
268	    remove(file);
269	    (void)mprotect(mem, pageSize, PROT_READ | PROT_WRITE | PROT_EXEC);
270	    (void)mprotect(reinterpret_cast<uint8_t*>(mem) + size - pageSize, pageSize, PROT_READ | PROT_WRITE | PROT_EXEC);
271	}
272	
273	void CheckGmValied(int argn, uint64_t* argv)
274	{
275	    for (int i = 0; i < argn; i++) {
276	        int ret = mprotect(reinterpret_cast<void*>(argv[i] & 0xfff), 0x1000, PROT_READ | PROT_WRITE);
277	        if (ret != 0) {
278	            continue;
279	        }
280	        ShmMemT* mem = reinterpret_cast<ShmMemT*>(GmGetHeader((void*)argv[i]));
281	        if (mem->magicCode != 0xdeadbeef) {
282	            std::cout << "The address of args are not allocate by AscendC::GmAlloc!" << std::endl;
283	            raise(SIGABRT);
284	        }
285	    }
286	}
