288	void CheckBlockdimForFfts(uint64_t numBlocks)
289	{
290	    (void)(numBlocks);
291	#if defined(__NPU_ARCH__) && __NPU_ARCH__ == 2201
292	    if ((g_kernelMode == KernelMode::MIX_MODE && numBlocks > MAX_CORE_NUM_V220) ||
293	        (g_kernelMode == KernelMode::AIC_MODE && numBlocks > MAX_CORE_NUM_V220) ||
294	        (g_kernelMode == KernelMode::AIV_MODE && numBlocks > MAX_CORE_NUM_V220 * AIV_IN_GROUP_CORE_NUM)) {
295	        std::cout << "The input numBlocks " << numBlocks << " exceed max core num of ascend910B1!" << std::endl;
296	        raise(SIGABRT);
297	    }
298	#endif
299	}
300	
301	void CheckNumBlocksForFfts(uint64_t numBlocks) { CheckBlockdimForFfts(numBlocks); }
302	
303	void SetGCoreType(int type)
304	{
305	    if (type < MIX_TYPE || type > AIV_TYPE) {
306	        std::cout << "Error g_coreType!" << std::endl;
307	        raise(SIGABRT);
308	    }
309	    g_coreType = type;
310	}
311	
312	void SetArgInfoList(const std::vector<ArgInfoT>& argInfoList) { GetArgInfoList() = argInfoList; }
313	} // namespace AscendC
